26	/// 一条本机骑行记录的详情：地图为主，底部条上滑把地图挤到半屏看数据。
27	class RideDetailPage extends StatefulWidget {
28	  /// 创建详情页。
29	  const RideDetailPage({super.key});
30	
31	  @override
32	  State<RideDetailPage> createState() => _RideDetailPageState();
33	}
