35	class _RideDetailPageState extends State<RideDetailPage>
36	    with TickerProviderStateMixin {
37	  final _shotKey = GlobalKey();
38	  final _map = MapController();
39	  final _shareMap = MapController();
40	  RideRecord? _rec;
41	  GpxSummary? _sum;
42	  List<LatLng> _pts = const [];
43	  List<LatLng> _disp = const [];
44	  bool _sharing = false;
45	  late final AnimationController _sheet;
46	
47	  @override
48	  void initState() {
49	    super.initState();
50	    final name = Get.arguments as String?;
51	    if (name != null) {
52	      _rec = RideRecordStore().find(name);
53	    }
54	    _loadPts();
55	    _sheet = AnimationController(
56	      vsync: this,
57	      duration: const Duration(milliseconds: 280),
58	    )..addStatusListener((status) {
59	        if (status == AnimationStatus.completed ||
60	            status == AnimationStatus.dismissed) {
61	          _fitLive();
62	        }
63	      });
64	  }
65	
66	  @override
67	  void dispose() {
68	    _map.dispose();
69	    _shareMap.dispose();
70	    _sheet.dispose();
71	    super.dispose();
72	  }
