74	  Future<void> _loadPts() async {
75	    final rec = _rec;
76	    if (rec == null) return;
77	    final f = File(rec.localPath);
78	    if (!await f.exists()) return;
79	    final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
80	    final sum = GpxUtil.parse(xml);
81	    if (!mounted) return;
82	    setState(() {
83	      _sum = sum;
84	      _pts = sum.points;
85	      _disp = HelmOsmTiles.toDisplayAll(sum.points);
86	    });
87	  }
88	
89	  static const _mapPad = EdgeInsets.fromLTRB(40, 48, 40, 40);
90	  static const _mapPadPeek = EdgeInsets.fromLTRB(36, 80, 36, 100);
91	  static const _peekBody = 56.0;
92	
93	  void _fitLive() {
94	    if (!mounted || _disp.length < 2) return;
95	    final fit = _fitOf(
96	      _disp,
97	      padding: _sheet.value > 0.5 ? _mapPad : _mapPadPeek,
98	    );
99	    if (fit == null) return;
100	    try {
101	      _map.fitCamera(fit);
102	    } catch (_) {}
103	  }
104	
105	  void _onSheetDragUpdate(double dy, double bodyH) {
106	    final travel = bodyH * 0.5 - _peekBody;
107	    if (travel <= 8) return;
108	    if (_sheet.isAnimating) _sheet.stop();
109	    _sheet.value = (_sheet.value - dy / travel).clamp(0.0, 1.0);
110	  }
111	
112	  void _onSheetDragEnd(double velocity) {
113	    final next = velocity < -350
114	        ? 1.0
115	        : velocity > 350
116	            ? 0.0
117	            : _sheet.value >= 0.45
118	                ? 1.0
119	                : 0.0;
120	    _sheet.animateTo(next, curve: Curves.easeOutCubic);
121	  }
122	
123	  CameraFit? _fitOf(List<LatLng> pts, {EdgeInsets padding = _mapPad}) {
124	    if (pts.length < 2) return null;
125	    return CameraFit.bounds(
126	      bounds: LatLngBounds.fromPoints(pts),
127	      padding: padding,
128	      maxZoom: 16,
129	      minZoom: 3,
130	      forceIntegerZoomLevel: true,
131	    );
132	  }
133	
134	  /// 用控件真实尺寸算出第一帧相机，避免先对着起点再跳到整条轨迹。
135	  ({LatLng center, double zoom})? _cameraFor(
136	    List<LatLng> pts,
137	    Size size, {
138	    EdgeInsets padding = _mapPad,
139	  }) {
140	    final fit = _fitOf(pts, padding: padding);
141	    if (fit == null || size.width < 8 || size.height < 8) return null;
142	    try {
143	      final fitted = fit.fit(
144	        MapCamera(
145	          crs: const Epsg3857(),
146	          center: pts.first,
147	          zoom: 10,
148	          rotation: 0,
149	          nonRotatedSize: size,
150	          minZoom: 3,
151	          maxZoom: 18,
152	        ),
153	      );
154	      return (center: fitted.center, zoom: fitted.zoom);
155	    } catch (_) {
156	      return null;
157	    }
158	  }
159	
160	  void _fitTrack(MapController map) {
161	    final fit = _fitOf(_disp, padding: _mapPadPeek);
162	    if (fit == null) return;
163	    try {
164	      map.fitCamera(fit);
165	    } catch (_) {}
166	  }
