218	  Future<void> _shareImage() async {
219	    final rec = _rec;
220	    if (rec == null || _sharing) return;
221	    setState(() => _sharing = true);
222	    try {
223	      await WidgetsBinding.instance.endOfFrame;
224	      if (!mounted) return;
225	      if (_pts.length >= 2) {
226	        _fitTrack(_shareMap);
227	        await Future<void>.delayed(const Duration(milliseconds: 700));
228	      }
229	      if (!mounted) return;
230	      final boundary =
231	          _shotKey.currentContext?.findRenderObject() as RenderRepaintBoundary?;
232	      if (boundary == null) {
233	        throw StateError('map not ready');
234	      }
235	      final dpr = MediaQuery.devicePixelRatioOf(context).clamp(2.0, 3.0);
236	      final image = await boundary.toImage(pixelRatio: dpr);
237	      final bytes = await image.toByteData(format: ui.ImageByteFormat.png);
238	      if (bytes == null) {
239	        throw StateError('empty png');
240	      }
241	      final dir = await getTemporaryDirectory();
242	      final stem = rec.fileName.toLowerCase().endsWith('.gpx')
243	          ? rec.fileName.substring(0, rec.fileName.length - 4)
244	          : rec.fileName;
245	      final file = File(p.join(dir.path, 'helm_$stem.png'));
246	      await file.writeAsBytes(bytes.buffer.asUint8List(), flush: true);
247	      final caption = RidePoster.shareCaption(rec, _sum);
248	      await SharePlus.instance.share(
249	        ShareParams(
250	          files: [
251	            XFile(file.path, mimeType: 'image/png', name: '${rec.title}.png'),
252	          ],
253	          text: caption,
254	        ),
255	      );
256	    } catch (e, st) {
257	      if (!mounted) return;
258	      AppTheme.fail(LocaleKeys.rideShareImage.tr, 'RideShare', e, st);
259	    } finally {
260	      if (mounted) setState(() => _sharing = false);
261	    }
262	  }
