429	  Widget _mapView(MapController controller, {EdgeInsets fitPad = _mapPad}) {
430	    if (_disp.isEmpty) {
431	      return const ColoredBox(
432	        color: Color(0xFFEDE8DF),
433	        child: Center(
434	          child: Icon(Icons.map_outlined, color: AppTheme.muted, size: 48),
435	        ),
436	      );
437	    }
438	    return LayoutBuilder(
439	      builder: (context, box) {
440	        final mapSize = Size(box.maxWidth, box.maxHeight);
441	        if (mapSize.width < 8 || mapSize.height < 8) {
442	          return const ColoredBox(color: Color(0xFFEDE8DF));
443	        }
444	        final cam = _cameraFor(_disp, mapSize, padding: fitPad);
445	        return FlutterMap(
446	          mapController: controller,
447	          options: MapOptions(
448	            initialCenter: cam?.center ?? _disp.first,
449	            initialZoom: cam?.zoom ?? 14,
450	            minZoom: 3,
451	            maxZoom: 18,
452	            interactionOptions: const InteractionOptions(
453	              flags: InteractiveFlag.all & ~InteractiveFlag.rotate,
454	            ),
455	            backgroundColor: const Color(0xFFEDE8DF),
456	          ),
457	          children: [
458	            HelmOsmTiles.layer(
459	              tileDisplay: const TileDisplay.instantaneous(),
460	            ),
461	            ...rideTrackLayers(
462	              display: _disp,
463	              summary: _sum,
464	              wgs: _pts,
465	            ),
466	          ],
467	        );
468	      },
469	    );
470	  }
