7	/// 与码表一致：慢绿 / 巡航青 / 快红。
8	abstract class RideTrackStyle {
9	  static Color speedColor(double kph) {
10	    var v = kph;
11	    if (v < 0) v = 0;
12	    if (v < 18) {
13	      final t = v / 18;
14	      return Color.fromARGB(
15	        255,
16	        (20 + 20 * t).round(),
17	        (168 + 42 * t).round(),
18	        (72 + 28 * t).round(),
19	      );
20	    }
21	    if (v < 32) {
22	      final t = (v - 18) / 14;
23	      return Color.fromARGB(
24	        255,
25	        (40 * (1 - t)).round(),
26	        (210 - 50 * t).round(),
27	        (100 + 120 * t).round(),
28	      );
29	    }
30	    final t = ((v - 32) / 16).clamp(0.0, 1.0);
31	    return Color.fromARGB(
32	      255,
33	      (255 * t).round(),
34	      (160 * (1 - t)).round(),
35	      (220 * (1 - t) + 32 * t).round(),
36	    );
37	  }
38	
39	  /// 沿轨迹把速度做滑动平均，再抽成少量色标，画一条渐变线。
40	  static List<Polyline> speedPolylines(
41	    List<LatLng> disp,
42	    List<double> speedsAtPoint, {
43	    double? fallbackKmh,
44	  }) {
45	    if (disp.length < 2) return const [];
46	    final fb = fallbackKmh ?? 18;
47	    final colors = _avgGradient(disp.length, speedsAtPoint, fb);
48	    return [
49	      Polyline(
50	        points: disp,
51	        strokeWidth: 9,
52	        color: const Color(0xEEFFFFFF),
53	      ),
54	      Polyline(
55	        points: disp,
56	        strokeWidth: 5,
57	        color: colors[colors.length ~/ 2],
58	        gradientColors: colors,
59	      ),
60	    ];
61	  }
62	
63	  static List<Color> _avgGradient(
64	    int n,
65	    List<double> speeds,
66	    double fallback,
67	  ) {
68	    final smooth = _smooth(n, speeds, fallback);
69	    const stops = 8;
70	    if (smooth.length == 1) {
71	      return [speedColor(smooth.first), speedColor(smooth.first)];
72	    }
73	    return [
74	      for (var i = 0; i < stops; i++)
75	        speedColor(
76	          smooth[((i / (stops - 1)) * (smooth.length - 1)).round()],
77	        ),
78	    ];
79	  }
80	
81	  static List<double> _smooth(
82	    int n,
83	    List<double> speeds,
84	    double fallback,
85	  ) {
86	    final raw = List<double>.generate(n, (i) {
87	      if (i < speeds.length && speeds[i] > 0.2) return speeds[i];
88	      return fallback;
89	    });
90	    final win = (n / 10).round().clamp(6, 48);
91	    final out = List<double>.filled(n, fallback);
92	    for (var i = 0; i < n; i++) {
93	      var s = 0.0;
94	      var c = 0;
95	      final a = i - win;
96	      final b = i + win;
97	      for (var j = a; j <= b; j++) {
98	        if (j < 0 || j >= n) continue;
99	        s += raw[j];
100	        c++;
101	      }
102	      out[i] = c == 0 ? fallback : s / c;
103	    }
104	    return out;
105	  }
106	}
