121	class _StartGridPainter extends CustomPainter {
122	  const _StartGridPainter();
123	
124	  @override
125	  void paint(Canvas canvas, Size size) {
126	    final c = Offset(size.width / 2, size.height / 2);
127	    final r = size.shortestSide / 2;
128	    canvas.drawCircle(
129	      c,
130	      r,
131	      Paint()
132	        ..color = const Color(0x66000000)
133	        ..maskFilter = const MaskFilter.blur(BlurStyle.normal, 1.4),
134	    );
135	    canvas.save();
136	    canvas.clipPath(
137	      Path()..addOval(Rect.fromCircle(center: c, radius: r - 1.6)),
138	    );
139	    const n = 4;
140	    final cell = (r * 2) / n;
141	    final origin = Offset(c.dx - r, c.dy - r);
142	    for (var y = 0; y < n; y++) {
143	      for (var x = 0; x < n; x++) {
144	        canvas.drawRect(
145	          Rect.fromLTWH(
146	            origin.dx + x * cell,
147	            origin.dy + y * cell,
148	            cell + 0.4,
149	            cell + 0.4,
150	          ),
151	          Paint()..color = (x + y).isEven ? Colors.black : Colors.white,
152	        );
153	      }
154	    }
155	    canvas.restore();
156	    canvas.drawCircle(
157	      c,
158	      r - 0.9,
159	      Paint()
160	        ..style = PaintingStyle.stroke
161	        ..strokeWidth = 2.2
162	        ..color = Colors.white,
163	    );
164	    canvas.drawCircle(
165	      c,
166	      r - 0.2,
167	      Paint()
168	        ..style = PaintingStyle.stroke
169	        ..strokeWidth = 1
170	        ..color = Colors.black87,
171	    );
172	  }
173	
174	  @override
175	  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
176	}
