191	class _FinishFlagPainter extends CustomPainter {
192	  const _FinishFlagPainter();
193	
194	  @override
195	  void paint(Canvas canvas, Size size) {
196	    final poleX = size.width * 0.18;
197	    final base = Offset(poleX, size.height - 1);
198	    canvas.drawLine(
199	      Offset(poleX, 2),
200	      base,
201	      Paint()
202	        ..color = const Color(0xFF1A1A1A)
203	        ..strokeWidth = 2.2
204	        ..strokeCap = StrokeCap.round,
205	    );
206	    const cols = 5;
207	    const rows = 4;
208	    final flag = Rect.fromLTWH(
209	      poleX + 1,
210	      3,
211	      size.width * 0.72,
212	      size.height * 0.52,
213	    );
214	    final cw = flag.width / cols;
215	    final ch = flag.height / rows;
216	    canvas.save();
217	    canvas.clipRRect(
218	      RRect.fromRectAndRadius(flag, const Radius.circular(1.5)),
219	    );
220	    for (var y = 0; y < rows; y++) {
221	      for (var x = 0; x < cols; x++) {
222	        canvas.drawRect(
223	          Rect.fromLTWH(
224	            flag.left + x * cw,
225	            flag.top + y * ch,
226	            cw + 0.3,
227	            ch + 0.3,
228	          ),
229	          Paint()..color = (x + y).isEven ? Colors.black : Colors.white,
230	        );
231	      }
232	    }
233	    canvas.restore();
234	    canvas.drawRRect(
235	      RRect.fromRectAndRadius(flag, const Radius.circular(1.5)),
236	      Paint()
237	        ..style = PaintingStyle.stroke
238	        ..strokeWidth = 1
239	        ..color = Colors.black87,
240	    );
241	    canvas.drawCircle(base, 2.2, Paint()..color = Colors.black87);
242	  }
243	
244	  @override
245	  bool shouldRepaint(covariant CustomPainter oldDelegate) => false;
246	}
