9	/// 从码表 `mtp/record/` 拉回的骑行文件。
10	class RideRecord {
11	  RideRecord({
12	    required this.fileName,
13	    required this.localPath,
14	    required this.size,
15	    required this.mtime,
16	    this.distanceKm,
17	    this.pointCount,
18	    this.durationSec,
19	    this.preview,
20	    this.displayName,
21	    this.remoteSize,
22	    this.userRenamed = false,
23	  });
24	
25	  final String fileName;
26	  final String localPath;
27	  final int size;
28	  final int mtime;
29	  final double? distanceKm;
30	  final int? pointCount;
31	
32	  /// GPX 起止时间差（秒）。`null` 表示索引里还没有算过。
33	  final int? durationSec;
34	
35	  /// 缩略轨迹。`null` 还没抽过；空列表表示没有可用点。
36	  final List<LatLng>? preview;
37	
38	  final String? displayName;
39	
40	  /// 码表上原文件大小，用来判断是否要重新拉。不用 BLE mtime。
41	  final int? remoteSize;
42	
43	  /// 用户在手机上改过显示名；再同步时保留，不跟 GPX 里的 `<name>` 覆盖。
44	  final bool userRenamed;
45	
46	  String get title {
47	    final n = displayName?.trim();
48	    if (n != null && n.isNotEmpty) return n;
49	    final stem = fileName.toLowerCase().endsWith('.gpx')
50	        ? fileName.substring(0, fileName.length - 4)
51	        : fileName;
52	    return stem;
53	  }
54	
55	  Map<String, Object?> toJson() => {
56	        'fileName': fileName,
57	        'localPath': localPath,
58	        'size': size,
59	        'mtime': mtime,
60	        'distanceKm': distanceKm,
61	        'pointCount': pointCount,
62	        'durationSec': durationSec,
63	        'preview': preview == null
64	            ? null
65	            : [
66	                for (final p in preview!) [p.latitude, p.longitude],
67	              ],
68	        'displayName': displayName,
69	        'remoteSize': remoteSize,
70	        'userRenamed': userRenamed,
71	      };
72	
73	  factory RideRecord.fromJson(Map<String, Object?> json) {
74	    return RideRecord(
