116	/// 主页统计区间。默认本周。
117	enum RidePeriod { week, month, all }
118	
119	/// 按记录时间过滤周 / 月 / 全部。
120	abstract class RidePeriodFilter {
121	  static DateTime weekStart(DateTime now) {
122	    final day = DateTime(now.year, now.month, now.day);
123	    return day.subtract(Duration(days: day.weekday - 1));
124	  }
125	
126	  static DateTime monthStart(DateTime now) => DateTime(now.year, now.month, 1);
127	
128	  static bool matches(RideRecord rec, RidePeriod period, DateTime now) {
129	    if (period == RidePeriod.all) return true;
130	    if (rec.mtime <= 0) return false;
131	    final t = DateTime.fromMillisecondsSinceEpoch(rec.mtime * 1000);
132	    final start =
133	        period == RidePeriod.week ? weekStart(now) : monthStart(now);
134	    return !t.isBefore(start);
135	  }
136	
137	  static List<RideRecord> apply(List<RideRecord> items, RidePeriod period) {
138	    final now = DateTime.now();
139	    return [for (final r in items) if (matches(r, period, now)) r];
140	  }
141	}
