143	/// 本机骑行记录库（documents/rides）。
144	class RideRecordStore {
145	  factory RideRecordStore() => _instance;
146	  static final RideRecordStore _instance = RideRecordStore._();
147	  RideRecordStore._();
148	
149	  Directory? _dir;
150	  final List<RideRecord> _items = [];
151	
152	  List<RideRecord> get items => List.unmodifiable(_items);
153	
154	  Future<Directory> _ensureDir() async {
155	    if (_dir != null) return _dir!;
156	    final root = await getApplicationDocumentsDirectory();
157	    _dir = Directory(p.join(root.path, 'rides'));
158	    if (!await _dir!.exists()) {
159	      await _dir!.create(recursive: true);
160	    }
161	    return _dir!;
162	  }
163	
164	  File get _indexFile => File(p.join(_dir!.path, 'index.json'));
165	
166	  /// 从磁盘加载。
167	  Future<void> load() async {
168	    await _ensureDir();
169	    _items.clear();
170	    if (!await _indexFile.exists()) return;
171	    try {
172	      final raw = jsonDecode(await _indexFile.readAsString());
173	      if (raw is List) {
174	        for (final e in raw) {
175	          if (e is Map<String, dynamic>) {
176	            _items.add(RideRecord.fromJson(Map<String, Object?>.from(e)));
177	          }
178	        }
179	      }
180	    } catch (_) {
181	      _items.clear();
182	    }
183	    _items.sort((a, b) => b.mtime.compareTo(a.mtime));
184	  }
185	
186	  Future<void> _flush() async {
187	    await _ensureDir();
188	    await _indexFile.writeAsString(
189	      jsonEncode(_items.map((e) => e.toJson()).toList()),
190	    );
191	  }
192	
193	  RideRecord? find(String fileName) {
194	    for (final e in _items) {
195	      if (e.fileName == fileName) return e;
196	    }
197	    return null;
198	  }
199	
200	  /// 写入或覆盖一条本机记录。时间取 GPX `<time>`，不采用码表 FS mtime。
201	  Future<RideRecord> putFile({
202	    required String fileName,
203	    required List<int> bytes,
204	    int? remoteSize,
205	    DateTime? stampUtc,
206	  }) async {
207	    await _ensureDir();
208	    final safe = GpxUtil.safeFileName(fileName);
209	    var xml = GpxUtil.ensureTimestamps(
210	      utf8.decode(bytes, allowMalformed: true),
211	      nowUtc: stampUtc,
212	    );
213	    final prev = find(safe);
214	    final keepName = prev != null &&
215	        prev.userRenamed &&
216	        (prev.displayName?.trim().isNotEmpty ?? false);
217	    if (keepName) {
218	      xml = GpxUtil.setName(xml, prev!.displayName!.trim());
219	    }
220	    final out = utf8.encode(xml);
221	    final file = File(p.join(_dir!.path, safe));
222	    await file.writeAsBytes(out, flush: true);
223	    final sum = GpxUtil.parse(xml);
224	    final when = sum.endTime ?? stampUtc ?? DateTime.now().toUtc();
225	    final rec = RideRecord(
226	      fileName: safe,
227	      localPath: file.path,
228	      size: out.length,
229	      mtime: GpxUtil.unixSeconds(when),
230	      distanceKm: sum.distanceKm,
231	      pointCount: sum.points.length,
232	      durationSec: sum.duration?.inSeconds ?? 0,
233	      preview: GpxUtil.previewTrack(sum.points),
234	      displayName: keepName
235	          ? prev!.displayName!.trim()
236	          : (sum.name.isEmpty ? null : sum.name),
237	      remoteSize: remoteSize,
238	      userRenamed: keepName,
239	    );
240	    _items.removeWhere((e) => e.fileName == safe);
241	    _items.insert(0, rec);
242	    _items.sort((a, b) => b.mtime.compareTo(a.mtime));
243	    await _flush();
244	    return rec;
245	  }
246	
247	  Future<void> remove(String fileName) async {
248	    await removeMany({fileName});
249	  }
250	
251	  /// 批量删除本机记录，不同步删码表文件。
252	  Future<void> removeMany(Set<String> fileNames) async {
253	    if (fileNames.isEmpty) return;
254	    await _ensureDir();
255	    for (final name in fileNames) {
256	      final rec = find(name);
257	      if (rec != null) {
258	        final f = File(rec.localPath);
259	        if (await f.exists()) await f.delete();
260	      }
261	    }
262	    _items.removeWhere((e) => fileNames.contains(e.fileName));
263	    await _flush();
264	  }
265	
266	  /// 只改手机显示名。本地文件名仍是码表 basename，再同步不会变成两条。
267	  Future<RideRecord?> setDisplayName(String fileName, String name) async {
268	    final rec = find(fileName);
269	    if (rec == null) return null;
270	    final trimmed = name.trim();
271	    if (trimmed.isEmpty) return rec;
272	    await _ensureDir();
273	    var size = rec.size;
274	    final f = File(rec.localPath);
275	    if (await f.exists()) {
276	      final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
277	      final out = utf8.encode(GpxUtil.setName(xml, trimmed));
278	      await f.writeAsBytes(out, flush: true);
279	      size = out.length;
280	    }
281	    final updated = rec.copyWith(
282	      size: size,
283	      displayName: trimmed,
284	      userRenamed: true,
285	    );
286	    final i = _items.indexWhere((e) => e.fileName == fileName);
287	    if (i >= 0) _items[i] = updated;
288	    await _flush();
289	    return updated;
290	  }
291	
292	  /// 给还没有时长 / 缩略轨迹的记录补 GPX 数据。
293	  Future<bool> ensureDurations() async {
294	    var changed = false;
295	    for (var i = 0; i < _items.length; i++) {
296	      final rec = _items[i];
297	      if (rec.durationSec != null && rec.preview != null) continue;
298	      var sec = rec.durationSec ?? 0;
299	      var preview = rec.preview;
300	      final f = File(rec.localPath);
301	      if (await f.exists()) {
302	        try {
303	          final xml = utf8.decode(await f.readAsBytes(), allowMalformed: true);
304	          final sum = GpxUtil.parse(xml);
305	          if (rec.durationSec == null) {
306	            sec = sum.duration?.inSeconds ?? 0;
307	          }
308	          preview ??= GpxUtil.previewTrack(sum.points);
309	        } catch (_) {
310	          preview ??= const [];
311	        }
312	      } else {
313	        preview ??= const [];
314	      }
315	      _items[i] = rec.copyWith(durationSec: sec, preview: preview);
316	      changed = true;
317	    }
318	    if (changed) await _flush();
319	    return changed;
320	  }
321	}
322	
323	List<LatLng>? _previewFromJson(Object? raw) {
324	  if (raw is! List) return null;
325	  final out = <LatLng>[];
326	  for (final e in raw) {
327	    if (e is List && e.length >= 2) {
328	      final lat = (e[0] as num?)?.toDouble();
329	      final lon = (e[1] as num?)?.toDouble();
330	      if (lat != null && lon != null) out.add(LatLng(lat, lon));
331	    }
332	  }
333	  return out;
334	}
