6	/// 折线 / 面积图，虚线标均值。
7	class RideSeriesChart extends StatelessWidget {
8	  const RideSeriesChart({
9	    super.key,
10	    required this.values,
11	    required this.color,
12	    this.fill = false,
13	    this.avg,
14	  });
15	
16	  final List<double> values;
17	  final Color color;
18	  final bool fill;
19	  final double? avg;
20	
21	  @override
22	  Widget build(BuildContext context) {
23	    return CustomPaint(
24	      painter: _SeriesPainter(
25	        values: downsample(values, 180),
26	        color: color,
27	        fill: fill,
28	        avg: avg,
29	      ),
30	      child: const SizedBox.expand(),
31	    );
32	  }
33	
34	  static List<double> downsample(List<double> src, int maxN) {
35	    if (src.length <= maxN) return src;
36	    final out = <double>[];
37	    for (var i = 0; i < maxN; i++) {
38	      final idx = (i * (src.length - 1) / (maxN - 1)).round();
39	      out.add(src[idx]);
40	    }
41	    return out;
42	  }
43	}
