45	class _SeriesPainter extends CustomPainter {
46	  _SeriesPainter({
47	    required this.values,
48	    required this.color,
49	    required this.fill,
50	    required this.avg,
51	  });
52	
53	  final List<double> values;
54	  final Color color;
55	  final bool fill;
56	  final double? avg;
57	
58	  @override
59	  void paint(Canvas canvas, Size size) {
60	    if (values.isEmpty || size.width < 8 || size.height < 8) return;
61	    const pad = EdgeInsets.fromLTRB(4, 10, 4, 6);
62	    final w = size.width - pad.left - pad.right;
63	    final h = size.height - pad.top - pad.bottom;
64	    if (w <= 0 || h <= 0) return;
65	
66	    var minV = values.reduce(math.min);
67	    var maxV = values.reduce(math.max);
68	    if (avg != null) {
69	      minV = math.min(minV, avg!);
70	      maxV = math.max(maxV, avg!);
71	    }
72	    if (maxV - minV < 0.2) {
73	      minV -= 1;
74	      maxV += 1;
75	    }
76	    final span = maxV - minV;
77	
78	    Offset pt(int i, double v) {
79	      final x = pad.left +
80	          (values.length == 1 ? w / 2 : w * i / (values.length - 1));
81	      final y = pad.top + h * (1 - (v - minV) / span);
82	      return Offset(x, y);
83	    }
84	
85	    final line = Path()..moveTo(pt(0, values[0]).dx, pt(0, values[0]).dy);
86	    for (var i = 1; i < values.length; i++) {
87	      line.lineTo(pt(i, values[i]).dx, pt(i, values[i]).dy);
88	    }
89	
90	    if (fill) {
91	      final area = Path.from(line)
92	        ..lineTo(pt(values.length - 1, values.last).dx, pad.top + h)
93	        ..lineTo(pad.left, pad.top + h)
94	        ..close();
95	      canvas.drawPath(
96	        area,
97	        Paint()
98	          ..shader = LinearGradient(
99	            begin: Alignment.topCenter,
100	            end: Alignment.bottomCenter,
101	            colors: [
102	              color.withValues(alpha: 0.42),
103	              color.withValues(alpha: 0.02),
104	            ],
105	          ).createShader(Offset.zero & size),
106	      );
107	    }
108	
109	    canvas.drawPath(
110	      line,
111	      Paint()
112	        ..color = color
113	        ..style = PaintingStyle.stroke
114	        ..strokeWidth = 2.2
115	        ..strokeJoin = StrokeJoin.round
116	        ..strokeCap = StrokeCap.round,
117	    );
118	
119	    final a = avg;
120	    if (a != null) {
121	      final y = pt(0, a).dy;
122	      _dash(
123	        canvas,
124	        Offset(pad.left, y),
125	        Offset(pad.left + w, y),
126	        Paint()
127	          ..color = color.withValues(alpha: 0.7)
128	          ..strokeWidth = 1.2,
129	      );
130	    }
131	  }
132	
133	  static void _dash(Canvas canvas, Offset a, Offset b, Paint paint) {
134	    const dash = 5.0;
135	    const gap = 4.0;
136	    final len = (b - a).distance;
137	    if (len < 1) return;
138	    final dir = (b - a) / len;
139	    var t = 0.0;
140	    while (t < len) {
141	      final end = math.min(t + dash, len);
142	      canvas.drawLine(a + dir * t, a + dir * end, paint);
143	      t += dash + gap;
144	    }
145	  }
146	
147	  @override
148	  bool shouldRepaint(covariant _SeriesPainter old) =>
149	      old.values != values ||
150	      old.color != color ||
151	      old.fill != fill ||
152	      old.avg != avg;
153	}
