158	
159	  final List<double> speeds;
160	
161	  @override
162	  Widget build(BuildContext context) {
163	    return SizedBox(
164	      height: 10,
165	      width: double.infinity,
166	      child: CustomPaint(
167	        painter: _PacePainter(speeds: RideSeriesChart.downsample(speeds, 120)),
