174	class _PacePainter extends CustomPainter {
175	  _PacePainter({required this.speeds});
176	
177	  final List<double> speeds;
178	
179	  static const _slow = Color(0xFF3DDC84);
180	  static const _mid = Color(0xFFFFD54A);
181	  static const _fast = Color(0xFFFF5C33);
182	
183	  @override
184	  void paint(Canvas canvas, Size size) {
185	    final r = RRect.fromRectAndRadius(
186	      Offset.zero & size,
187	      const Radius.circular(5),
188	    );
189	    canvas.save();
190	    canvas.clipRRect(r);
191	    if (speeds.length < 2) {
192	      canvas.drawRRect(
193	        r,
194	        Paint()
195	          ..shader = const LinearGradient(
196	            colors: [_slow, _mid, _fast],
197	          ).createShader(Offset.zero & size),
198	      );
199	    } else {
200	      var minV = speeds.reduce(math.min);
201	      var maxV = speeds.reduce(math.max);
202	      if (maxV - minV < 0.4) {
203	        minV -= 0.5;
204	        maxV += 0.5;
205	      }
206	      final span = maxV - minV;
207	      final w = size.width / speeds.length;
208	      for (var i = 0; i < speeds.length; i++) {
209	        final t = ((speeds[i] - minV) / span).clamp(0.0, 1.0);
210	        final c = t < 0.5
211	            ? Color.lerp(_slow, _mid, t * 2)!
212	            : Color.lerp(_mid, _fast, (t - 0.5) * 2)!;
213	        canvas.drawRect(Rect.fromLTWH(i * w, 0, w + 0.6, size.height), Paint()..color = c);
214	      }
215	    }
216	    canvas.restore();
217	  }
218	
219	  @override
220	  bool shouldRepaint(covariant _PacePainter old) => old.speeds != speeds;
221	}
