222	  static ({double? max, List<RideSeriesPoint> points, List<double> atPoint})
223	      _speedSeries(List<_GpxPt> pts) {
224	    var maxV = 0.0;
225	    final series = <RideSeriesPoint>[];
226	    final atPoint = List<double>.filled(pts.length, 0);
227	    var last = 0.0;
228	    for (var i = 1; i < pts.length; i++) {
229	      var v = last;
230	      final a = pts[i - 1].time;
231	      final b = pts[i].time;
232	      if (a != null && b != null) {
233	        final sec = b.difference(a).inMilliseconds / 1000.0;
234	        if (sec >= 0.8 && sec <= 60) {
235	          final km = _haversineKm(pts[i - 1].ll, pts[i].ll);
236	          final raw = km / (sec / 3600.0);
237	          if (raw > 0 && raw < 80) {
238	            v = raw;
239	            series.add(RideSeriesPoint(time: b, value: v));
240	            if (v > maxV) maxV = v;
241	          }
242	        }
243	      }
244	      atPoint[i] = v;
245	      last = v;
246	    }
247	    return (
248	      max: maxV > 0.5 ? maxV : null,
249	      points: series,
250	      atPoint: atPoint,
251	    );
252	  }
253	
254	  /// 沿轨迹每整公里一个点。
255	  static List<({LatLng ll, int km})> kmMarkers(
256	    List<LatLng> points, {
257	    double intervalKm = 1,
258	    int maxMarks = 120,
259	  }) {
260	    final out = <({LatLng ll, int km})>[];
261	    if (points.length < 2 || intervalKm <= 0) return out;
262	    var acc = 0.0;
263	    var next = intervalKm;
264	    var n = 1;
265	    for (var i = 1; i < points.length; i++) {
266	      final d = _haversineKm(points[i - 1], points[i]);
267	      if (d <= 0) continue;
268	      while (acc + d >= next && n <= maxMarks) {
269	        final t = ((next - acc) / d).clamp(0.0, 1.0);
270	        final a = points[i - 1];
271	        final b = points[i];
272	        out.add((
273	          ll: LatLng(
274	            a.latitude + (b.latitude - a.latitude) * t,
275	            a.longitude + (b.longitude - a.longitude) * t,
276	          ),
277	          km: n,
278	        ));
279	        n++;
280	        next += intervalKm;
281	      }
282	      acc += d;
283	    }
284	    return out;
285	  }
