368	  /// 心率区间累计（热身 / 燃脂 / 有氧 / 无氧 / 极限）。
369	  static List<Duration> hrZoneDurations(
370	    List<RideSeriesPoint> pts, {
371	    Duration? total,
372	  }) {
373	    final zones = List<Duration>.filled(5, Duration.zero);
374	    if (pts.isEmpty) return zones;
375	    final fallbackMs =
376	        (total?.inMilliseconds ?? pts.length * 1000) ~/ pts.length;
377	    for (var i = 0; i < pts.length; i++) {
378	      var ms = fallbackMs;
379	      if (i + 1 < pts.length) {
380	        final a = pts[i].time;
381	        final b = pts[i + 1].time;
382	        if (a != null && b != null) {
383	          final d = b.difference(a).inMilliseconds;
384	          if (d > 0 && d <= 120000) ms = d;
385	        }
386	      }
387	      if (ms <= 0) continue;
388	      final z = hrZoneIndex(pts[i].value.round());
389	      zones[z] += Duration(milliseconds: ms);
390	    }
391	    return zones;
392	  }
