419	  /// 文件里按出现顺序的可信 UTC 时间（忽略码表未校时的 1970/2000）。
420	  static List<DateTime> plausibleTimes(String xml) {
421	    final out = <DateTime>[];
422	    for (final match in _timeRe.allMatches(xml)) {
423	      final t = tryParseUtc(match.group(1)!);
424	      if (t != null && isPlausibleTime(t)) {
425	        out.add(t);
