440	  /// GNSS / 手机时间：2020 年之后、且不超过「现在 + 2 天」。
441	  static bool isPlausibleTime(DateTime t) {
442	    final u = t.toUtc();
443	    final now = DateTime.now().toUtc();
444	    return u.year >= 2020 && !u.isAfter(now.add(const Duration(days: 2)));
445	  }
