459	  /// 相邻点球面距离之和，千米。
460	  static double distanceKm(List<LatLng> points) {
461	    var sum = 0.0;
462	    for (var i = 1; i < points.length; i++) {
463	      sum += _haversineKm(points[i - 1], points[i]);
464	    }
465	    return sum;
466	  }
467	
468	  static double _haversineKm(LatLng a, LatLng b) {
469	    const r = 6371.0;
470	    final dLat = _rad(b.latitude - a.latitude);
471	    final dLon = _rad(b.longitude - a.longitude);
472	    final x = math.sin(dLat / 2) * math.sin(dLat / 2) +
473	        math.cos(_rad(a.latitude)) *
474	            math.cos(_rad(b.latitude)) *
475	            math.sin(dLon / 2) *
476	            math.sin(dLon / 2);
477	    return 2 * r * math.asin(math.min(1, math.sqrt(x)));
478	  }
479	
480	  static double _rad(double deg) => deg * math.pi / 180;
481	
482	  /// 列表缩略图用：保留起终点，中间均匀抽点。
483	  static List<LatLng> previewTrack(List<LatLng> points, {int max = 48}) {
484	    if (points.length <= 2) return List<LatLng>.from(points);
485	    if (points.length <= max) return List<LatLng>.from(points);
486	    final last = points.length - 1;
487	    final out = <LatLng>[];
488	    for (var i = 0; i < max; i++) {
489	      final idx = ((last * i) / (max - 1)).round();
490	      if (out.isEmpty || out.last != points[idx]) {
491	        out.add(points[idx]);
492	      }
493	    }
494	    if (out.last != points.last) out.add(points.last);
495	    return out;
496	  }
