707	      stem = stem.substring(0, stem.length - 4);
708	    }
709	    final buf = StringBuffer();
710	    for (final r in stem.runes) {
711	      final c = String.fromCharCode(r);
712	      if (RegExp(r'[A-Za-z0-9._\u4e00-\u9fff-]').hasMatch(c)) {
713	        buf.write(c);
714	      } else if (c == ' ') {
715	        buf.write('_');
