718	    var out = buf.toString();
719	    if (out.isEmpty) {
720	      out = 'route';
721	    }
722	    const ext = '.tsv';
723	    final cap = maxChars - ext.length;
724	    out = WaypointTsv.capUtf8(out, cap > 1 ? cap : 1);
725	    return '$out$ext';
