88	  List<Offset> _map(Size size) {
89	    var minLat = points.first.latitude;
90	    var maxLat = minLat;
91	    var minLon = points.first.longitude;
92	    var maxLon = minLon;
93	    for (final p in points) {
94	      minLat = math.min(minLat, p.latitude);
95	      maxLat = math.max(maxLat, p.latitude);
96	      minLon = math.min(minLon, p.longitude);
97	      maxLon = math.max(maxLon, p.longitude);
98	    }
99	    final midLat = (minLat + maxLat) / 2;
100	    final k = math.cos(midLat * math.pi / 180).clamp(0.2, 1.0);
101	    var minX = minLon * k;
102	    var maxX = maxLon * k;
103	    var minY = minLat;
104	    var maxY = maxLat;
105	    var dx = maxX - minX;
106	    var dy = maxY - minY;
107	    if (dx < 1e-9) dx = 1e-9;
108	    if (dy < 1e-9) dy = 1e-9;
109	    final innerW = size.width - _pad * 2;
110	    final innerH = size.height - _pad * 2;
111	    final scale = math.min(innerW / dx, innerH / dy);
112	    final ox = _pad + (innerW - dx * scale) / 2;
113	    final oy = _pad + (innerH - dy * scale) / 2;
114	    return [
115	      for (final p in points)
116	        Offset(
117	          ox + (p.longitude * k - minX) * scale,
118	          oy + (maxY - p.latitude) * scale,
119	        ),
120	    ];
121	  }
